/**
 * @description Pickers and summary facts of the guided setup: the Apex classes that implement an Integration Hub
 * interface (concrete, test classes left out), the Named Credentials of the org and the Integration Hub permission
 * set of the inbound user.
 * @group Integration Hub
 */
public with sharing class IntegrationHubSetupOptions {

    private static final String ADMIN_SET = 'Integration_Hub_Admin';
    private static final String READ_SET = 'Integration_Hub_Read';
    private static final String IMPLEMENTORS = 'SELECT ApexClassId, ClassName, ClassNamespacePrefix FROM ApexTypeImplementor '
        + 'WHERE InterfaceName = :name AND IsConcrete = true LIMIT 1000';
    private static final Map<String, Type> INTERFACE_OF_KIND = new Map<String, Type>{
        'payload' => IntegrationHub.IPayloadBuilder.class,
        'response' => IntegrationHub.IResponseHandler.class,
        'inbound' => IntegrationHub.IInboundHandler.class,
        'auth' => IntegrationHub.IConnectionAuth.class
    };

    /**
     * @description Concrete classes implementing the interface of a kind. The interface may be listed as
     * IntegrationHub.IPayloadBuilder or IPayloadBuilder, so both are asked; every class is then checked with
     * Type.isAssignableFrom. Classes whose body contains @IsTest are left out; a hidden body counts as not a test.
     * @param kind payload, response, inbound or auth
     * @return the class names, sorted
     */
    public static List<IntegrationHubSetup.Option> classOptions(String kind) {
        Type iface = interfaceOf(kind);
        String fullName = iface.getName();
        List<SObject> rows = new List<SObject>();
        rows.addAll(IntegrationHubData.query(IMPLEMENTORS, new Map<String, Object>{ 'name' => fullName }));
        rows.addAll(IntegrationHubData.query(IMPLEMENTORS, new Map<String, Object>{ 'name' => fullName.substringAfterLast('.') }));
        Map<Id, ApexClass> classes = classesOf(rows);
        Set<String> names = new Set<String>();
        for (SObject row : rows) {
            ApexClass cls = classes.get((Id) row.get('ApexClassId'));
            if (cls != null && !isTest(cls)) {
                String name = classNameOf(row, cls);
                if (isUsable(name, iface)) {
                    names.add(name);
                }
            }
        }
        List<IntegrationHubSetup.Option> out = new List<IntegrationHubSetup.Option>();
        for (String name : names) {
            out.add(new IntegrationHubSetup.Option(name, name, null));
        }
        out.sort();
        return out;
    }

    /**
     * @description Named Credentials of the org.
     * @return value = API name (with namespace prefix when packaged), label = label, detail = URL
     */
    public static List<IntegrationHubSetup.Option> namedCredentials() {
        List<IntegrationHubSetup.Option> out = new List<IntegrationHubSetup.Option>();
        for (SObject nc : IntegrationHubData.query(
                'SELECT DeveloperName, MasterLabel, NamespacePrefix, Endpoint FROM NamedCredential ORDER BY MasterLabel LIMIT 1000', null)) {
            String prefix = (String) nc.get('NamespacePrefix');
            String developerName = (String) nc.get('DeveloperName');
            out.add(new IntegrationHubSetup.Option(String.isBlank(prefix) ? developerName : prefix + '__' + developerName,
                (String) nc.get('MasterLabel'), (String) nc.get('Endpoint')));
        }
        return out;
    }

    /**
     * @description The Integration Hub permission set of a user.
     * @param userId the user (may be null)
     * @return Integration Hub Admin, Integration Hub Read, or null when the user has neither
     */
    public static String userAccess(Id userId) {
        if (userId == null) {
            return null;
        }
        Set<String> sets = new Set<String>();
        for (SObject a : IntegrationHubData.query('SELECT PermissionSet.Name FROM PermissionSetAssignment '
                + 'WHERE AssigneeId = :uid AND PermissionSet.Name IN :names LIMIT 10',
                new Map<String, Object>{ 'uid' => userId, 'names' => new List<String>{ ADMIN_SET, READ_SET } })) {
            sets.add((String) a.getSObject('PermissionSet').get('Name'));
        }
        if (sets.contains(ADMIN_SET)) {
            return 'Integration Hub Admin';
        }
        return sets.contains(READ_SET) ? 'Integration Hub Read' : null;
    }

    /**
     * @description True when a Named Credential of this API name exists in the org.
     * @param credential the API name (may be blank)
     * @return whether it exists
     */
    public static Boolean credentialExists(String credential) {
        if (String.isBlank(credential)) {
            return false;
        }
        for (IntegrationHubSetup.Option o : namedCredentials()) {
            if (o.value.equalsIgnoreCase(credential.trim())) {
                return true;
            }
        }
        return false;
    }

    private static Type interfaceOf(String kind) {
        Type iface = INTERFACE_OF_KIND.get(kind == null ? '' : kind.toLowerCase());
        if (iface == null) {
            throw IntegrationHubPreview.auraError('Unknown class kind: ' + kind + '. Use payload, response, inbound or auth.');
        }
        return iface;
    }

    private static Map<Id, ApexClass> classesOf(List<SObject> rows) {
        Set<Id> ids = new Set<Id>();
        for (SObject row : rows) {
            ids.add((Id) row.get('ApexClassId'));
        }
        Map<Id, ApexClass> out = new Map<Id, ApexClass>();
        if (ids.isEmpty()) {
            return out;
        }
        for (SObject c : IntegrationHubData.query('SELECT Id, Name, NamespacePrefix, Body FROM ApexClass WHERE Id IN :ids',
                new Map<String, Object>{ 'ids' => ids })) {
            out.put(c.Id, (ApexClass) c);
        }
        return out;
    }

    /* A test class, or a class inside one (IntegrationHubTestData.StubPayloadBuilder), is never offered. Comments are
       removed first, so a handler that only mentions @IsTest in its ApexDoc is still offered. */
    @TestVisible
    private static Boolean isTest(ApexClass cls) {
        if (cls.Body == null) {
            return false;
        }
        String code = cls.Body;
        try {
            code = code.replaceAll('(?s)/\\*.*?\\*/', ' ').replaceAll('//[^\\n]*', ' ');
        } catch (Exception e) {
            // A very long body can be too much for the regex: then any @IsTest in it counts.
            code = cls.Body;
        }
        return code.toLowerCase().contains('@istest');
    }

    /* ClassName may be the inner name only (StubPayloadBuilder) or Outer.Inner; the outer class comes from ApexClass. */
    private static String classNameOf(SObject row, ApexClass cls) {
        String name = (String) row.get('ClassName');
        if (String.isBlank(name)) {
            name = cls.Name;
        }
        if (!name.contains('.') && !name.equalsIgnoreCase(cls.Name)) {
            name = cls.Name + '.' + name;
        }
        String prefix = (String) row.get('ClassNamespacePrefix');
        if (String.isNotBlank(prefix) && !name.startsWithIgnoreCase(prefix + '.')) {
            name = prefix + '.' + name;
        }
        return name;
    }

    /* The framework creates the class with Type.forName(name): offer only names that resolve to the interface. */
    private static Boolean isUsable(String name, Type iface) {
        Type t = Type.forName(name);
        return t != null && iface.isAssignableFrom(t);
    }
}
